71	func jobFileName(id uint64) string {
72		return fmt.Sprintf("job-%020d.json", id)
73	}
74	
75	func (s *Store) jobPath(j *storedJob) string {
76		return filepath.Join(s.dir, jobFileName(j.id))
77	}
78	
79	func encodeRecord(j *storedJob) ([]byte, error) {
80		r := jobRecord{
81			Version: recordVersion,
82	
83			ID:            j.id,
84			Submitter:     j.submitter,
85			RequestID:     j.requestID,
86			Seed:          j.seed,
87			Values:        append([]int64(nil), j.values...),
88			HasDependency: len(j.dependencies) > 0,
89			DependencyID:  depID(j),
90			Dependencies:  append([]uint64(nil), j.dependencies...),
91	
92			QueuedAt:      j.queuedAt,
93			StartedAt:     j.startedAt,
94			FinishedAt:    j.finishedAt,
95			Status:        j.status,
96			FailureReason: j.failureReason,
97			BlockerID:     j.blockerID,
98	
99			EffectiveValues: append([]int64(nil), j.effectiveValues...),
100			Archive:         j.archive,
101		}
102		return json.MarshalIndent(&r, "", "  ")
103	}
104	
105	// depID 返回首个直接上游作业号（无依赖时为 0）。
106	func depID(j *storedJob) uint64 {
107		if len(j.dependencies) == 0 {
108			return 0
109		}
110		return j.dependencies[0]
111	}
112	
113	// persist 在已持锁的情况下原子写一条作业记录。
114	func (s *Store) persist(j *storedJob) error {
115		data, err := encodeRecord(j)
116		if err != nil {
117			return err
118		}
119		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
120	}
121	
122	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
123	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
124	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
125		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
126		if err != nil {
127			return err
128		}
129		tmpName := tmp.Name()
130		cleanup := true
131		defer func() {
132			if cleanup {
133				_ = os.Remove(tmpName)
134			}
135		}()
136	
137		if _, err := tmp.Write(data); err != nil {
138			_ = tmp.Close()
139			return err
140		}
141		if err := tmp.Sync(); err != nil {
142			_ = tmp.Close()
143			return err
144		}
145		if err := tmp.Close(); err != nil {
146			return err
147		}
148		if err := os.Chmod(tmpName, perm); err != nil {
149			return err
150		}
151		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
152			return err
153		}
154		cleanup = false
155		syncDir(dir)
156		return nil
157	}
158	
159	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
160	func syncDir(dir string) {
161		if d, err := os.Open(dir); err == nil {
162			_ = d.Sync()
163			_ = d.Close()
164		}
165	}
