1	package numeric
2	
3	import (
4		"errors"
5		"io/fs"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// makeArchiveReadOnly 把归档目录临时变为目录本身不可写（无法创建临时文件、
13	// 无法 rename 替换记录），并在测试结束时自动恢复，避免污染 t.TempDir 的清理。
14	// 若当前权限模型下只读目录仍可写（例如以 root 运行），故障注入无法成立，
15	// 跳过测试而不是误报失败。
16	func makeArchiveReadOnly(t *testing.T, dir string) {
17		t.Helper()
18		if err := os.Chmod(dir, 0o500); err != nil {
19			t.Fatalf("chmod 0500: %v", err)
20		}
21		t.Cleanup(func() { _ = os.Chmod(dir, 0o700) })
22		probe := filepath.Join(dir, ".tmp-write-probe")
23		if err := os.WriteFile(probe, []byte("x"), 0o600); err == nil {
24			_ = os.Remove(probe)
25			_ = os.Chmod(dir, 0o700)
26			t.Skip("只读目录在当前环境下仍可写，无法注入保存失败（通常为 root 运行）")
27		}
28	}
29	
30	func makeArchiveWritable(t *testing.T, dir string) {
31		t.Helper()
32		if err := os.Chmod(dir, 0o700); err != nil {
33			t.Fatalf("chmod 0700: %v", err)
34		}
35	}
36	
37	// 排队作业取消时无法保存：返回实际保存错误，作业在内存与磁盘上都保持排队，
38	// 不新增完成时间、不清空信息、不级联下游；写入恢复后重新取消才生效，
39	// 重新打开归档仍保留这次已确认的取消，且作业号与提交参数不变。
40	func TestCancelQueuedPersistFailureKeepsStateAndRetries(t *testing.T) {
41		dir := t.TempDir()
42		s, err := Open(dir, WithClock(newManualClock()))
43		if err != nil {
44			t.Fatal(err)
45		}
46		started, block, release, _, _ := gateCompute(t, s)
47		block(1)
48	
49		head := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
50		waitStarted(t, started, head.ID)
51		q := mustSubmit(t, s, SubmitRequest{
52			Submitter: "a", RequestID: "cq", Values: []int64{5}, Seed: 7,
53		})
54		child := mustSubmit(t, s, SubmitRequest{
55			Submitter: "a", Values: []int64{9},
56			HasDependency: true, DependencyID: q.ID,
57		})
58	
59		onDisk := func() string {
60			data, err := os.ReadFile(filepath.Join(dir, jobFileName(q.ID)))
61			if err != nil {
62				t.Fatal(err)
63			}
64			return string(data)
65		}
66		if !strings.Contains(onDisk(), `"status": "queued"`) {
67			t.Fatal("queued job not persisted as queued before cancel")
68		}
69	
70		// 目录暂时不可写：取消必须返回底层错误，不能返回任何成功视图。
71		makeArchiveReadOnly(t, dir)
72		if cj, err := s.Cancel(q.ID); err == nil {
73			t.Fatalf("cancel with unwritable dir returned success: %+v", cj)
74		} else if !errors.Is(err, fs.ErrPermission) {
75			t.Fatalf("cancel err=%v, want the actual save error (permission denied)", err)
76		}
77		// 首次未保存的取消不能被当成已完成操作：紧接着的重复请求同样失败。
78		if _, err := s.Cancel(q.ID); !errors.Is(err, fs.ErrPermission) {
79			t.Fatalf("repeat cancel while unwritable err=%v, want permission error", err)
80		}
81	
82		// 内存可查询状态保持原状态：仍排队、无完成时间、保留参数、等待计算位置。
83		g, _ := s.Get(q.ID)
84		if g.Status != StatusQueued || !g.FinishedAt.IsZero() || g.WaitReason != WaitSlot {
85			t.Fatalf("job changed after failed cancel: status=%s finished=%s reason=%q",
86				g.Status, g.FinishedAt, g.WaitReason)
87		}
88		if g.ID != q.ID || g.Submitter != "a" || g.RequestID != "cq" ||
89			g.Seed != 7 || len(g.Values) != 1 || g.Values[0] != 5 {
90			t.Fatalf("submit params altered after failed cancel: %+v", g)
91		}
92		// 运行中的作业未被提前中止，等待依赖的下游也没有仅因这次请求被标记失败。
93		if h, _ := s.Get(head.ID); h.Status != StatusRunning || !h.FinishedAt.IsZero() {
94			t.Fatalf("running job disturbed by failed cancel: %+v", h)
95		}
96		c, _ := s.Get(child.ID)
97		if c.Status != StatusQueued || c.WaitReason != WaitDependency || !c.FinishedAt.IsZero() {
98			t.Fatalf("downstream disturbed by failed cancel: %+v", c)
99		}
100		// 磁盘上仍是原来的排队记录。
101		if !strings.Contains(onDisk(), `"status": "queued"`) ||
102			strings.Contains(onDisk(), `"status": "canceled"`) {
103			t.Fatalf("disk record changed despite failed cancel:\n%s", onDisk())
104		}
105	
106		// 写入恢复：对仍排队的同一作业重新取消，成功后才返回取消状态。
107		makeArchiveWritable(t, dir)
108		cj, err := s.Cancel(q.ID)
109		if err != nil || cj.Status != StatusCanceled || cj.FinishedAt.IsZero() {
110			t.Fatalf("retry cancel: view=%+v err=%v", cj, err)
111		}
112		if cj.ID != q.ID || cj.RequestID != "cq" || cj.Seed != 7 ||
113			len(cj.Values) != 1 || cj.Values[0] != 5 {
114			t.Fatalf("confirmed cancel must keep job id and submit params: %+v", cj)
115		}
116		// 已成功保存的取消允许重复请求返回成功。
117		if again, err := s.Cancel(q.ID); err != nil || again.Status != StatusCanceled {
118			t.Fatalf("repeat confirmed cancel: %+v %v", again, err)
119		}
120		// 直到取消确认后，依赖它的下游才按现有规则失败并指出阻断作业。
121		fc := waitStatus(t, s, child.ID, StatusFailed)
122		if fc.BlockerID != q.ID || !strings.Contains(fc.FailureReason, "取消") {
123			t.Fatalf("downstream failure after confirmed cancel: %+v", fc)
124		}
125	
126		release(head.ID)
127		waitStatus(t, s, head.ID, StatusSucceeded)
128		if err := s.Close(); err != nil {
129			t.Fatal(err)
130		}
131	
132		// 重新打开同一归档：已确认的取消与下游失败都保留。
133		s2, err := Open(dir)
134		if err != nil {
135			t.Fatal(err)
136		}
137		defer s2.Close()
138		rq, _ := s2.Get(q.ID)
139		if rq.Status != StatusCanceled || rq.FinishedAt.IsZero() || rq.Archive != nil {
140			t.Fatalf("canceled job after reopen: %+v", rq)
141		}
142		if rq.ID != q.ID || rq.RequestID != "cq" || rq.Seed != 7 ||
143			len(rq.Values) != 1 || rq.Values[0] != 5 {
144			t.Fatalf("job params changed across reopen: %+v", rq)
145		}
146		rc, _ := s2.Get(child.ID)
147		if rc.Status != StatusFailed || rc.BlockerID != q.ID {
148			t.Fatalf("downstream after reopen: %+v", rc)
149		}
150	}
151	
152	// 运行中的作业取消保存失败时，不中止计算：计算随后成功，第二次取消返回
153	// 已有的不能取消错误并保留成功结果；溢出场景下计算仍正常失败，同样不可再取消。
154	func TestCancelRunningPersistFailureLetsComputeFinish(t *testing.T) {
155		s, _ := openTestStore(t)
156		started, block, release, _, _ := gateCompute(t, s)
157		block(1)
158		run := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
159		waitStarted(t, started, run.ID)
160	
161		makeArchiveReadOnly(t, s.Dir())
162		cj, err := s.Cancel(run.ID)
163		if !errors.Is(err, fs.ErrPermission) || cj != nil {
164			t.Fatalf("cancel running while unwritable: view=%+v err=%v", cj, err)
165		}
166		g, _ := s.Get(run.ID)
167		if g.Status != StatusRunning || g.StartedAt.IsZero() || !g.FinishedAt.IsZero() {
168			t.Fatalf("running job changed after failed cancel: %+v", g)
169		}
170		data, err := os.ReadFile(filepath.Join(s.Dir(), jobFileName(run.ID)))
171		if err != nil {
172			t.Fatal(err)
173		}
174		if !strings.Contains(string(data), `"status": "running"`) {
175			t.Fatalf("disk record must stay running after failed cancel:\n%s", data)
176		}
177	
178		// 计算在两次取消请求之间成功完成。
179		makeArchiveWritable(t, s.Dir())
180		release(run.ID)
181		done := waitStatus(t, s, run.ID, StatusSucceeded)
182		if done.Archive == nil || done.Archive.Sum != 1 {
183			t.Fatalf("compute must still be allowed to succeed: %+v", done)
184		}
185		if _, err := s.Cancel(run.ID); !errors.Is(err, ErrNotCancellable) {
186			t.Fatalf("cancel after success: %v, want ErrNotCancellable", err)
187		}
188		again, _ := s.Get(run.ID)
189		if again.Status != StatusSucceeded || again.Archive == nil ||
190			again.Archive.Checksum != done.Archive.Checksum {
191			t.Fatalf("succeeded result must be preserved, got %+v", again)
192		}
193	
194		// 同样的保存失败不应妨碍计算正常失败（输入溢出）。
195		block(2)
196		big := int64(3037000500)
197		bad := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{big}})
198		waitStarted(t, started, bad.ID)
199		makeArchiveReadOnly(t, s.Dir())
200		if _, err := s.Cancel(bad.ID); !errors.Is(err, fs.ErrPermission) {
201			t.Fatalf("cancel overflow job while unwritable: %v", err)
202		}
203		makeArchiveWritable(t, s.Dir())
204		release(bad.ID)
205		failed := waitStatus(t, s, bad.ID, StatusFailed)
206		if !strings.Contains(failed.FailureReason, "平方和") || failed.Archive != nil {
207			t.Fatalf("overflow job must still fail normally: %+v", failed)
208		}
209		if _, err := s.Cancel(bad.ID); !errors.Is(err, ErrNotCancellable) {
210			t.Fatalf("cancel failed job: %v, want ErrNotCancellable", err)
211		}
212		if g, _ := s.Get(bad.ID); g.Status != StatusFailed ||
213			g.FailureReason != failed.FailureReason || g.Archive != nil {
214			t.Fatalf("failed result changed after rejected cancel: %+v", g)
215		}
216	}
217	
218	// 排队作业取消保存失败本身不改变调度：恢复写入但不重新取消、放行前面的作业后，
219	// 该作业仍按原有排队规则正常计算并成功。
220	func TestFailedQueuedCancelDoesNotChangeScheduling(t *testing.T) {
221		s, _ := openTestStore(t)
222		started, block, release, _, _ := gateCompute(t, s)
223		block(1)
224		head := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
225		waitStarted(t, started, head.ID)
226		q := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{5}})
227	
228		makeArchiveReadOnly(t, s.Dir())
229		if _, err := s.Cancel(q.ID); !errors.Is(err, fs.ErrPermission) {
230			t.Fatalf("cancel: %v", err)
231		}
232		makeArchiveWritable(t, s.Dir())
233		if g, _ := s.Get(q.ID); g.Status != StatusQueued {
234			t.Fatalf("job must remain queued after failed cancel: %s", g.Status)
235		}
236	
237		release(head.ID)
238		done := waitStatus(t, s, q.ID, StatusSucceeded)
239		if done.Archive.Sum != 5 {
240			t.Fatalf("queued job must still run normally, sum=%d", done.Archive.Sum)
241		}
242	}
243	
244	// 取消成功保存后，正在运行的计算即使随后“成功完成”也不能留下成功归档；
245	// 关闭重开归档后，已确认的取消仍然成立。
246	func TestConfirmedRunningCancelDiscardsLateSuccess(t *testing.T) {
247		dir := t.TempDir()
248		s, err := Open(dir)
249		if err != nil {
250			t.Fatal(err)
251		}
252		// 自定义钩子：放行后无视取消信号、照常返回成功结果，模拟计算在取消确认
253		// 之后才结束的竞态。
254		started := make(chan uint64, 1)
255		gate := make(chan struct{})
256		s.compute = func(_ uint64, _ []int64, _ int64, _ func() bool) (int64, int64, string, bool) {
257			started <- 1
258			<-gate
259			return 3, 5, "", true
260		}
261		run := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2}})
262		waitStarted(t, started, run.ID)
263	
264		cj, err := s.Cancel(run.ID)
265		if err != nil || cj.Status != StatusCanceled {
266			t.Fatalf("cancel running: %+v %v", cj, err)
267		}
268		if g, _ := s.Get(run.ID); g.Status != StatusCanceled || g.FinishedAt.IsZero() {
269			t.Fatalf("query right after confirmed cancel: %+v", g)
270		}
