	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	for _, want := range []struct {
		id      uint64
		blocker uint64
	}{
		{up.ID, 0}, {child.ID, up.ID}, {grand.ID, up.ID},
	} {
		j, _ := s2.Get(want.id)
		if j.Status != StatusFailed || j.BlockerID != want.blocker || j.Archive != nil {
